const required = require('requires-port');
const qs = require('querystringify');
const CRHTLF = /[\n\r\t]/g;
const slashes = /^[A-Za-z][A-Za-z0-9+-.]*:\/\//;
const protocolre = /^([a-z][a-z0-9.+-]*:)(\/\/)([^\/\s]+)([\S\s]*)$/i;
const windowsDriveLetter = /^[a-zA-Z]:[\\\/]/;
const whitespace = /^[\s\p{Zs}]+/u;
const allowedProtocols = ['http:', 'https:', 'ftp:', 'file:'];

function sanitizeUrl(url) {
    if (typeof url !== 'string') {
        throw new TypeError('URL must be a string');
    }

    // Remove control characters and trim
    url = url.replace(CRHTLF, '').trim();

    // Validate protocol
    const protocolMatch = url.match(protocolre);
    if (!protocolMatch || !allowedProtocols.includes(protocolMatch[1].toLowerCase())) {
        throw new Error('Invalid or disallowed protocol');
    }

    // Normalize path separators
    if (protocolMatch[1].toLowerCase() === 'file:') {
        if (!windowsDriveLetter.test(url)) {
            throw new Error('Invalid file path');
        }
        url = url.replace(/\\/g, '/');
    }

    // Remove leading/trailing whitespace
    url = url.replace(whitespace, '');

    return url;
}

