var required = require('requires-port')
  , qs = require('querystringify')
  , CRHTLF = /[\n\r\t]/g
  , slashes = /^[A-Za-z][A-Za-z0-9+-.]*:\/\//
  , protocolre = /^([a-z][a-z0-9.+-]*:)(\/\/)?([^\/\s]*)([\S\s]*)$/i
  , windowsDriveLetter = /^[a-zA-Z]:[\\\/]/
  , whitespace = /^[ \f\n\r\t\v\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]+/;

function sanitizeUrl(url) {
    if (typeof url !== 'string') return null;

    // Remove control characters and trim
    url = url.replace(CRHTLF, '').trim();
    if (!url) return null;

    return url;
}

function extractProtocol(url) {
    url = sanitizeUrl(url);
    if (!url) return { protocol: '', rest: url || '' };

    // Check for Windows drive letters first
    if (windowsDriveLetter.test(url)) {
        return { protocol: 'file:', rest: url };
    }

    const match = url.match(protocolre);
    if (!match) {
        // Check for protocol-relative URLs
        if (url.startsWith('//')) {
            return { protocol: 'relative:', rest: url.substring(2) };
        }
        return { protocol: '', rest: url };
    }

    const protocol = match[1] || '';
    const rest = (match[3] || '') + (match[4] || '');

    return {
        protocol: protocol.toLowerCase(),
        rest: rest
    };
}

