func Clean(p string) string {
	// Normalize path separators
	normalized := strings.ReplaceAll(p, "\\", "/")

	// Clean the path and ensure it's rooted
	cleaned := path.Clean("/" + normalized)

	// Check for path traversal attempts
	if strings.Contains(cleaned, "../") || cleaned == ".." {
		// If path contains traversal, clean again from root
		cleaned = path.Clean("/" + strings.ReplaceAll(cleaned, "../", ""))
	}

	// Verify the path doesn't escape root
	if !strings.HasPrefix(cleaned, "/") {
		return ""
	}

	// Trim leading/trailing slashes
	result := strings.Trim(cleaned, "/")

	// Handle edge case where path becomes empty after cleaning
	if result == "." || result == "" {
		return ""
	}

	return result
}

