		return false
	case strings.HasPrefix(redirect, "/") && !strings.HasPrefix(redirect, "//") && !invalidRedirectRegex.MatchString(redirect):
		return true
	case strings.HasPrefix(redirect, "http://") || strings.HasPrefix(redirect, "https://"):
		redirectURL, err := url.Parse(redirect)
		if err != nil {
			logger.Printf("Rejecting invalid redirect %q: scheme unsupported or missing", redirect)
			return false
		}
		redirectHostname := redirectURL.Hostname()

		for _, domain := range p.whitelistDomains {
			domainHostname, domainPort := splitHostPort(strings.TrimLeft(domain, "."))
			if domainHostname == "" {
				continue
			}

			if strings.HasPrefix(domain, ".") {
				// For domains starting with ".", require exact match after the dot or proper subdomain
				if redirectHostname == domainHostname || 
				   (strings.HasSuffix(redirectHostname, domainHostname) && 
				    strings.HasSuffix(redirectHostname, "."+domainHostname)) {
					// Validate ports
					redirectPort := redirectURL.Port()
					if (domainPort == "*") ||
						(domainPort == redirectPort) ||
						(domainPort == "" && redirectPort == "") {
						return true
					}
				}
			} else {
				// For exact domains, require full match
				if redirectHostname == domainHostname {
					// Validate ports
					redirectPort := redirectURL.Port()
					if (domainPort == "*") ||
						(domainPort == redirectPort) ||
