func isRepositoryGitPath(path string) bool {
	// Normalize path separators and clean the path
	normalizedPath := filepath.ToSlash(filepath.Clean(path))

	// Check for .git suffix or .git/ in path
	if strings.HasSuffix(normalizedPath, ".git") || 
	   strings.Contains(normalizedPath, ".git/") {
		return true
	}

	// Additional check for Windows-specific cases
	if runtime.GOOS == "windows" {
		lowerPath := strings.ToLower(normalizedPath)
		if strings.HasSuffix(lowerPath, ".git.") || 
		   strings.Contains(lowerPath, ".git.\\") {
			return true
		}
	}

	return false
}

