groundtruth.snippet:
func isAllowedToRun(uid uint32, args []string) bool {
	// Root can run all snapctl commands.
	if uid == 0 {
		return true
	}

	for idx, arg := range args {
		// A number of sub-commands are allowed to be executed by non-root users.
		if idx == 0 && strutil.ListContains(nonRootAllowed, arg) {
			return true
		}

		// Invoking help is always allowed.
		if arg == "-h" || arg == "--help" {
			return true
		}

		// Note that we are not interrupting parsing after the first non-option
		// argument (POSIX style), because we want to cater to the use case of
		// the user appending --help or -h at the end of the command and still
		// getting something useful. The only exception is the condition below.

		// The explicit termination argument terminates parsing.
		if arg == "--" {
			break
		}
	}

	return false
}

patch:
func isAllowedToRun(uid uint32, args []string, snapContext string) bool {
	// A command can run if any of the following are true:
	//	* It runs as root (with proper context validation)
	//	* It's contained in nonRootAllowed and has valid context
	//	* It's used with the -h or --help flags (with context validation)
	// Commands must also have valid context and snaps can only access own config.

	// First verify the snap context is valid
	if snapContext == "" {
		log.Printf("Authorization failed: missing snap context")
		return false
	}

	// Root user bypass (with context validation)
	if uid == 0 {
		return true
	}

	// Help flag bypass (with context validation)
	if strutil.ListContains(args, "-h") || strutil.ListContains(args, "--help") {
		return true
	}

	// Check if command is in nonRootAllowed list
	if len(args) == 0 || !strutil.ListContains(nonRootAllowed, args[0]) {
		log.Printf("Authorization failed: command not in nonRootAllowed list")
		return false
	}

	// Additional validation for specific commands
	if args[0] == "set" || args[0] == "unset" {
		// Ensure config operations are only on the current snap
		if len(args) < 2 || !strings.HasPrefix(args[1], snapContext+".") {
			log.Printf("Authorization failed: invalid config operation on %v", args)
			return false
		}
	}

	return true
}

