func isRepositoryGitPath(path string) bool {
	// Normalize the path first
	cleanPath := filepath.Clean(path)

	// Convert to lowercase for case-insensitive comparison (Windows compatibility)
	lowerPath := strings.ToLower(cleanPath)

	// Check for .git suffix or .git/ directory
	return strings.HasSuffix(lowerPath, ".git") ||
		strings.Contains(lowerPath, ".git/") ||
		strings.Contains(lowerPath, ".git\\") ||
		// Windows treats ".git." the same as ".git"
		strings.HasSuffix(lowerPath, ".git.") ||
		strings.Contains(lowerPath, ".git./") ||
		strings.Contains(lowerPath, ".git.\\")
}

