var (
	// ErrNeedsLogin means the user should be redirected to the login page
	ErrNeedsLogin = errors.New("redirect to login page")

	// Used to check final redirects are not susceptible to open redirects.
	// Matches various forms of potentially malicious redirect patterns including:
	// - //, /\, / /, / \\, /\s/, etc.
	// - URLs with scheme but not matching trusted domains
	invalidRedirectRegex = regexp.MustCompile(`^(?:\s*)(?:(?:[/\\]\s*[/\\])|(?:[a-zA-Z]+:\/\/))`)
)

// isValidRedirect checks if the redirect URL is safe
func isValidRedirect(redirect string, trustedDomains []string) bool {
	// Check for malicious patterns first
	if invalidRedirectRegex.MatchString(redirect) {
		return false
	}

	// Parse the URL to check host
	u, err := url.Parse(redirect)
	if err != nil {
		// If it's not a valid URL but is a relative path, allow it
		return strings.HasPrefix(redirect, "/") && !strings.Contains(redirect, "//")
	}

	// If no host specified (relative URL), allow it
	if u.Host == "" {
		return true
	}

	// Check against trusted domains
	for _, domain := range trustedDomains {
		if strings.EqualFold(u.Host, domain) {
			return true
		}
		// Handle subdomains if needed
		if strings.HasSuffix(u.Host, "."+domain) {
			return true
		}
	}

	return false
}

