// isValidTenantID checks if the tenant ID contains only allowed characters
func isValidTenantID(id string) bool {
	for _, r := range id {
		if !(r >= 'a' && r <= 'z') && !(r >= 'A' && r <= 'Z') && !(r >= '0' && r <= '9') && r != '-' && r != '_' {
			return false
		}
	}
	return true
}

