	// Strict comparison of all URL components
	if !isLoopbackAddress(requested.Host) {
		return false
	}

	// Compare normalized paths
	if path.Clean(registered.Path) != path.Clean(requested.Path) {
		return false
	}

	// Compare hostnames exactly
	if registered.Hostname() != requested.Hostname() {
		return false
	}

	// Compare ports if present
	if registered.Port() != requested.Port() {
		return false
	}

	return true
}

