const { execFile } = require('child_process');
const path = require('path');

module.exports = function(image, output, cb) {
  // Validate input parameters
  if (typeof image !== 'string' || !image.trim()) {
    return cb(new Error('Invalid image parameter'));
  }
  if (typeof output !== 'object' || output === null) {
    return cb(new Error('Invalid output parameter'));
  }

  try {
    // Get command and args safely
    const { command, args } = module.exports.getSafeCommand(image, output);

    // Use execFile instead of exec to avoid shell interpretation
    execFile(command, args, {timeout: 30000}, function(e, stdout, stderr) {
      if (e) { return cb(e); }
      if (stderr) { return cb(new Error(stderr)); }

      return cb(null, output.versions);
    });
  } catch (err) {
    return cb(err);
  }
};

module.exports.getSafeCommand = function(image, output) {
  // Validate and sanitize image path
  const sanitizedImage = path.normalize(image).replace(/[�-"&<>\^|]/g, '');

  // Build safe arguments array
  const args = [];
  args.push(sanitizedImage);

  // Add output options if they exist
  if (output.width) args.push('--width', String(output.width));
  if (output.height) args.push('--height', String(output.height));
  if (output.quality) args.push('--quality', String(output.quality));

  // Return command and args separately
  return {
    command: 'im-resize', // Assuming this is the executable name
    args: args
  };
};

