const path = require('path');

module.exports = function(image, output, cb) {
  // Validate input parameters
  if (typeof image !== 'string' || !image.trim()) {
    return cb(new Error('Invalid image parameter: must be a non-empty string'));
  }
  if (typeof output !== 'object' || output === null) {
    return cb(new Error('Invalid output parameter: must be an object'));
  }

  try {
    // Sanitize and validate image path
    const sanitizedImage = path.resolve(image);
    if (!sanitizedImage) {
      return cb(new Error('Invalid image path'));
    }

    // Build safe arguments array
    const args = [sanitizedImage];

    // Validate and add output parameters
    if (output.width) {
      const width = parseInt(output.width, 10);
      if (isNaN(width) || width <= 0) {
        return cb(new Error('Invalid width parameter'));
      }
      args.push('--width', String(width));
    }

    if (output.height) {
      const height = parseInt(output.height, 10);
      if (isNaN(height) || height <= 0) {
        return cb(new Error('Invalid height parameter'));
      }
      args.push('--height', String(height));
    }

    if (output.quality) {
      const quality = parseInt(output.quality, 10);
      if (isNaN(quality) || quality <= 0 || quality > 100) {
        return cb(new Error('Invalid quality parameter'));
      }
      args.push('--quality', String(quality));
    }

    // Execute the command safely
    execFile('im-resize', args, {timeout: 30000}, function(e, stdout, stderr) {
      if (e) { return cb(e); }
      if (stderr) { return cb(new Error(stderr)); }
      return cb(null, output.versions);
    });
  } catch (err) {
    return cb(err);
  }
};

