module.exports = function whereis(name, cb) {
  // Validate input to prevent command injection
  if (typeof name !== 'string' || !/^[a-zA-Z0-9\-_.]+$/.test(name)) {
    return cb(new Error('Invalid name parameter'));
  }

  const commands = [
    { cmd: 'which', args: [name] },
    { cmd: 'whereis', args: [name] },
    { cmd: 'where', args: [name] },
    { cmd: 'cmd.exe', args: ['/c', 'for %i in (' + name + '.exe) do @echo. %~$PATH:i'] }
  ];

  function tryCommand(index) {
    if (index >= commands.length) {
      return cb(new Error('Could not find ' + name + ' on your system'));
    }

    const { cmd, args } = commands[index];
    cp.execFile(cmd, args, { shell: false }, function(error, stdout, stderr) {
      stdout = stdout ? stdout.split('\n')[0].trim() : '';

      if (cmd === 'which' && !error && !stderr && stdout && stdout.charAt(0) === '/') {
        return cb(null, stdout);
      }

      if (cmd === 'whereis' && !error && !stderr && stdout && stdout.indexOf('/') !== -1) {
        return cb(null, stdout.split(' ')[1]);
      }

      if (cmd === 'where' && !error && !stderr && stdout && stdout.indexOf('\\') !== -1) {
        return cb(null, stdout);
      }

      if (cmd === 'cmd.exe' && !error && !stderr && stdout && stdout.indexOf('\\') !== -1) {
        return cb(null, stdout);
      }

      tryCommand(index + 1);
    });
  }

  tryCommand(0);
};

