exports.killByPort = function (port) {
  // Validate port is a number between 1-65535
  if (typeof port !== 'number' || port < 1 || port > 65535) {
    throw new Error('Invalid port number');
  }

  var processId = null;
  try {
    // Use execFile with explicit arguments
    const { execFile } = require('child_process');
    processId = execFile('lsof', ['-t', '-i:' + port], (error, stdout, stderr) => {
      if (error) {
        return null;
      }
      return stdout.toString().trim();
    });
  } catch (e) {
    return;
  }

  if (processId !== null) {
    try {
      // Use execFile with explicit arguments
      const { execFile } = require('child_process');
      execFile('kill', [processId]);
    } catch (e) {
      // Handle kill error
    }
  }
}

