const isValidPackageName = (name) => {
  return /^[a-zA-Z0-9][a-zA-Z0-9_.-]*$/.test(name);
};

const isValidRegistryUrl = (url) => {
  if (!url) return true;
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
};

module.exports = function (packageName, { registry = '', timeout = null } = {}) {
    if (!isValidPackageName(packageName) || !isValidRegistryUrl(registry)) {
        return null;
    }

    try {
        let version;
        const args = ['view', packageName, 'version'];
        if (registry) {
            args.push('--registry', registry);
        }

        const config = {
            stdio: ['pipe', 'pipe', 'ignore'],
            shell: false
        };

        if (timeout) {
            config.timeout = timeout;
        }

        const result = require('child_process').spawnSync('npm', args, config);
        version = result.stdout;

        if (version) {
            return version.toString().trim().replace(/^\n*/, '').replace(/\n*$/, '');
        } else {
            return null;
        }
    } catch(err) {
        return null;
    }
}

