def secure_join(root, *paths):
    "Join paths and ensure it still below root"
    if not os.path.isabs(root):
        raise IOError("Permission denied: Root path must be absolute")

    # Resolve all paths to their canonical form
    root = os.path.realpath(root)
    path = os.path.realpath(os.path.join(root, *paths))

    # Verify the path is within the root directory
    try:
        # Python 3.5+ preferred method
        if hasattr(os.path, 'commonpath'):
            if os.path.commonpath([root]) != os.path.commonpath([root, path]):
                raise IOError("Permission denied")
        else:
            # Fallback for older Python versions
            if not os.path.abspath(path).startswith(os.path.abspath(root) + os.sep):
                raise IOError("Permission denied")
    except ValueError:
        # Handle case where paths are on different drives (Windows)
        raise IOError("Permission denied")

    return path

