func validateRsyncArgs(args []string) ([]string, error) {
	allowedOptions := []string{
		"--recursive", "--times", "--perms", "--owner", "--group",
		"--devices", "--specials", "--links", "--hard-links",
		"--copy-links", "--safe-links", "--munge-links", "--relative",
		"--no-relative", "--archive", "--update", "--dirs",
		"--delete", "--delete-excluded", "--force", "--ignore-errors",
		"--verbose", "--quiet", "--compress", "--checksum",
		"--whole-file", "--partial", "--progress", "--stats",
		"--human-readable", "--bwlimit", "--timeout", "--contimeout",
		"--temp-dir", "--backup", "--backup-dir", "--suffix",
		"--list-only", "--dry-run", "--size-only", "--modify-window",
		"--max-size", "--min-size", "--exclude", "--include",
		"--filter", "--cvs-exclude", "--existing", "--ignore-existing",
		"--remove-source-files", "--prune-empty-dirs", "--delay-updates",
		"--password-file", "--port", "--chmod", "--fake-super",
	}

	optionWithParam := map[string]bool{
		"--bwlimit": true, "--timeout": true, "--contimeout": true,
		"--temp-dir": true, "--backup-dir": true, "--suffix": true,
		"--max-size": true, "--min-size": true, "--exclude": true,
		"--include": true, "--filter": true, "--password-file": true,
		"--port": true, "--chmod": true,
	}

	var validatedArgs []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "-") {
			validatedArgs = append(validatedArgs, arg)
			continue
		}

		found := false
		for _, opt := range allowedOptions {
			if arg == opt {
				found = true
				break
			}
			if strings.HasPrefix(arg, opt+"=") {
				found = true
				break
			}
		}

		if !found {
			return nil, fmt.Errorf("disallowed option: %s", arg)
		}

		if optionWithParam[strings.Split(arg, "=")[0]] {
			if !strings.Contains(arg, "=") {
				if i+1 >= len(args) {
					return nil, fmt.Errorf("missing parameter for option: %s", arg)
				}
				validatedArgs = append(validatedArgs, arg, args[i+1])
				i++
				continue
			}
		}

		validatedArgs = append(validatedArgs, arg)
	}

	return validatedArgs, nil
}

