      if (this.Model.rawAttributes.hasOwnProperty(key)) {
        sanitizedWhere[key] = where[key];
      }
    }
  }

  // Validate and sanitize select fields
  let attributes = null;
  if (filters.$select && Array.isArray(filters.$select)) {
    attributes = filters.$select.filter(field => 
      this.Model.rawAttributes.hasOwnProperty(field)
    );
