    where: sanitizedWhere,
    order,
    limit: filters.$limit,
    offset: filters.$skip,
    raw: this.raw,
    distinct: true
  }, 
  // Only allow specific sequelize options
  params.sequelize ? {
    transaction: params.sequelize.transaction,
    lock: params.sequelize.lock,
    logging: params.sequelize.logging
  } : {});

