def get_model_version_artifact_handler():
    from querystring_parser import parser
    from werkzeug.security import safe_join

    query_string = request.query_string.decode("utf-8")
    request_dict = parser.parse(query_string, normalized=True)
    name = request_dict.get("name")
    version = request_dict.get("version")
    artifact_uri = _get_model_registry_store().get_model_version_download_uri(name, version)

    if not request_dict.get("path"):
        raise ValueError("Path parameter is required")

    if _is_servable_proxied_run_artifact_root(artifact_uri):
        artifact_repo = _get_artifact_repo_mlflow_artifacts()
        artifact_path = _get_proxied_run_artifact_destination_path(
            proxied_artifact_root=artifact_uri,
            relative_path=request_dict["path"],
        )
    else:
        artifact_repo = get_artifact_repository(artifact_uri)
        try:
            artifact_path = safe_join(artifact_uri, request_dict["path"])
        except ValueError as e:
            raise ValueError("Invalid path provided") from e

    return _send_artifact(artifact_repo, artifact_path)

