const { execFile } = require('child_process');

module.exports = function (msg, silent) {
	var arg = '';

	// Validate silent parameter
	if (typeof silent !== 'boolean') {
		silent = true;
	}

	msg = makeDefault(msg);

	// Input validation for msg
	if (typeof msg !== 'string' && !Array.isArray(msg)) {
		throw new Error('Invalid message type');
	}

	if (Array.isArray(msg)) {
		if (msg.length) {
			msg.forEach(function (m) {
				m = makeDefault(m);
				if (typeof m !== 'string' || /[\x00-\x1F\x7F"$`\\]/.test(m)) {
					throw new Error('Invalid message content');
				}
				arg += '-m"' + m.replace(/"/g, '\\"') + '" ';
			});
		} else {
			arg = '-m"' + defaultMsg + '"';
		}
	} else {
		if (typeof msg !== 'string' || /[\x00-\x1F\x7F"$`\\]/.test(msg)) {
			throw new Error('Invalid message content');
		}
		arg = '-m"' + msg.replace(/"/g, '\\"') + '"';
	}

	const args = ['commit', ...arg.split(' '), '--allow-empty', '--no-gpg-sign'];

	execFile('git', args, { silent: silent }, (error) => {
		if (error) {
			throw error;
		}
	});
};

