res.location = function location(url) {
  var loc = url;
  var allowedHosts = this.app.get('allowedRedirectHosts') || [];
  var defaultRedirect = '/';

  // "back" is an alias for the referrer
  if (url === 'back') {
    var referrer = this.req.get('Referrer');
    if (referrer) {
      try {
        var referrerUrl = new URL(referrer);
        if (allowedHosts.includes(referrerUrl.hostname) || referrerUrl.hostname === this.req.hostname) {
          loc = referrer;
        } else {
          loc = defaultRedirect;
        }
      } catch (e) {
        loc = defaultRedirect;
      }
    } else {
      loc = defaultRedirect;
    }
  } else {
    try {
      if (url && typeof url === 'string') {
        var parsedUrl = new URL(url, 'http://' + this.req.headers.host);

        // Allow relative URLs and same-origin absolute URLs
        if (!parsedUrl.hostname || parsedUrl.hostname === this.req.hostname || allowedHosts.includes(parsedUrl.hostname)) {
          loc = url;
        } else {
          loc = defaultRedirect;
        }
      } else {
        loc = defaultRedirect;
      }
    } catch (e) {
      loc = defaultRedirect;
    }
  }

  // Set location header using encodeurl to prevent header injection
  this.set('Location', encodeUrl(loc));
  return this;
};

