_resolvePath(path = '.') {
  const clientPath = (() => {
    path = nodePath.normalize(path).replace(/\\/g, '/');
    if (nodePath.isAbsolute(path)) {
      return nodePath.join(path);
    } else {
      return nodePath.join(this.cwd, path);
    }
  })();

  const fsPath = (() => {
    const resolvedPath = nodePath.join(this.root, clientPath);
    const normalizedPath = nodePath.normalize(nodePath.join(resolvedPath)).replace(/\\/g, '/');
    if (!normalizedPath.startsWith(nodePath.normalize(this.root).replace(/\\/g, '/'))) {
      throw new Error('Invalid path: Attempt to access outside root directory');
    }
    return nodePath.resolve(normalizedPath);
  })();

  return {
    clientPath,
    fsPath
  };
}

