constructor(connection, {root, cwd} = {}) {
  this.connection = connection;
  this._root = nodePath.resolve(root || process.cwd());
  this.cwd = nodePath.normalize(cwd ? nodePath.join(nodePath.sep, cwd) : nodePath.sep).replace(/\\/g, '/');

  // Verify cwd is within root
  const resolvedCwd = nodePath.resolve(nodePath.join(this._root, this.cwd)).replace(/\\/g, '/');
  if (!resolvedCwd.startsWith(nodePath.normalize(this._root).replace(/\\/g, '/'))) {
    throw new Error('Invalid cwd: Must be within root directory');
  }
}

