		}

		if cert == nil {
			return fmt.Errorf("certificate not found")
		}

		// Validate subjectRegExp if provided
		if subjectRegExp != "" {
			re, err := regexp.Compile(subjectRegExp)
			if err != nil {
				return fmt.Errorf("invalid subject regex pattern: %w", err)
			}
			if !re.MatchString(cert.Subject.String()) {
				errs = append(errs, fmt.Errorf("certificate subject does not match required pattern"))
				continue
			}
		}

