module.exports = ruleSource => {
  let rules = [];
  const config = require('../config');
  const path = require('path');
  const safeDir = path.join(__dirname, '../rules'); // Define safe directory

  // polymorphic support
  if (Array.isArray(ruleSource)) {
    rules = ruleSource;
  } else if (ruleSource) {
    try {
      // Validate and normalize path
