const path = require('path');

module.exports = filepath => {
  // Normalize the path first to handle mixed slashes and resolve ./
  filepath = path.normalize(filepath);

  // Prevent path traversal attempts
  if (filepath.includes('..')) {
    throw new Error('Path traversal attempt detected');
  }

  let r = '';
  let remainingPath = filepath;

  while (isAbsolute(remainingPath)) {
    // Handle both Windows and Unix-style paths
    const root = remainingPath.charAt(0) === '/' ? 
      '/' : 
      path.parse(remainingPath).root;

    // Validate the root portion
    if (process.platform === 'win32' && root.match(/^[a-zA-Z]:[\\\/]/)) {
      // Ensure drive letter matches current working directory if relative
      if (root.charAt(1) === ':' && !remainingPath.startsWith(root)) {
        throw new Error('Invalid drive letter specification');
      }
    }

    remainingPath = remainingPath.substr(root.length);
    r += root;
  }

  return [r, remainingPath];
}

function isAbsolute(p) {
  if (process.platform === 'win32') {
    return path.win32.isAbsolute(p);
  } else {
    return path.posix.isAbsolute(p);
  }
}

