const path = require('path');

module.exports = (filepath) => {
  if (typeof filepath !== 'string') {
    return ['', ''];
  }

  // Handle Windows paths
  if (process.platform === 'win32') {
    // Normalize path separators first
    filepath = filepath.replace(/\//g, '\\');

    // Check for UNC paths
    if (filepath.startsWith('\\\\')) {
      const parts = filepath.split('\\').filter(Boolean);
      if (parts.length >= 2) {
        const root = `\\\\${parts[0]}\\${parts[1]}\\`;
        return [root, filepath.slice(root.length)];
      }
    }

    // Check for drive letters
    const driveMatch = filepath.match(/^([a-zA-Z]:\\)/);
    if (driveMatch) {
      return [driveMatch[1], filepath.slice(driveMatch[1].length)];
    }

    // Handle root paths
    if (filepath.startsWith('\\')) {
      return ['\\', filepath.slice(1)];
    }

    return ['', filepath];
  }

  // Handle Unix paths
  if (filepath.startsWith('/')) {
    // Handle multiple leading slashes
    const slashes = filepath.match(/^\/+/) || [''];
    const root = slashes[0].length > 1 ? '/' : '/'; // Preserve single slash for root
    return [root, filepath.slice(root.length)];
  }

  return ['', filepath];
};

