  // path => [function or Set]
  // A Set object means a directory reservation
  // A fn is a direct reservation on that path
  const queues = new Map()

  // fn => {paths:[path,...], dirs:[path, ...]}
  const reservations = new Map()

  // cache of resolved paths to detect collisions
  const resolvedPaths = new Map()
  const isWindows = platform() === 'win32'

  // normalize and resolve path with security checks
  const securePath = (path) => {
    // Normalize Unicode first
    let securePath = normalize(path.normalize('NFC'))

    // On Windows, resolve short path names
    if (isWindows) {
      try {
        securePath = realpathSync.native(securePath)
      } catch (_) {}
    }

    // Resolve to absolute path and normalize again
    securePath = normalize(join(securePath))

    // Check for path collisions using case-insensitive comparison on Windows
    const comparePath = isWindows ? securePath.toLowerCase() : securePath
