      const existing = resolvedPaths.get(comparePath)
      if (existing !== securePath && !isWindows) {
        throw new Error('Path collision detected: ' + 
          `${existing} and ${securePath} resolve to the same location`)
      }
    } else {
      resolvedPaths.set(comparePath, securePath)
    }

    return securePath
  }

