func (ctrl *ApplicationController) canProcessApp(obj interface{}) bool {
	app, ok := obj.(*appv1.Application)
	if !ok {
		return false
	}

	// Only process given app if it exists in a watched namespace, or in the
	// control plane's namespace.
	if app.Namespace != ctrl.namespace && !glob.MatchStringInList(ctrl.applicationNamespaces, app.Namespace, false) {
		return false
	}

	if ctrl.clusterFilter != nil {
		cluster, err := ctrl.db.GetCluster(context.Background(), app.Spec.Destination.Server)
		if err != nil {
			return ctrl.clusterFilter(nil)
		}
		return ctrl.clusterFilter(cluster)
	}

	return true
}

patch:
func (ctrl *ApplicationController) canProcessApp(obj interface{}) bool {
	app, ok := obj.(*appv1.Application)
	if !ok {
		return false
	}
	if ctrl.clusterFilter != nil {
		cluster, err := ctrl.db.GetCluster(context.Background(), app.Spec.Destination.Server)
		if err != nil {
			return ctrl.clusterFilter(nil)
		}
		return ctrl.clusterFilter(cluster)
	}

	// Only process given app if it exists in a watched namespace, or in the
	// control plane's namespace.
	if app.Namespace == ctrl.namespace {
		return true
	}

	if len(ctrl.applicationNamespaces) == 0 {
		return false
	}

	// Ensure strict namespace validation
	matched := false
	for _, nsPattern := range ctrl.applicationNamespaces {
		if glob.Match(nsPattern, app.Namespace) {
			matched = true
			break
		}
	}
	if !matched {
		return false
	}

	// Additional check to ensure the namespace is allowed by the AppProject
	proj, err := ctrl.getAppProj(app)
	if err != nil {
		return false
	}
	if len(proj.Spec.SourceNamespaces) > 0 && !slices.Contains(proj.Spec.SourceNamespaces, app.Namespace) {
		return false
	}

	return true
}

