                }
            }
            catch (err) {
                if (this.auth._timeout) {
                    clearTimeout(this.auth._timeout);
                }
            }
        });
    }
    catch (err) {
        if (this.auth._timeout) {
            clearTimeout(this.auth._timeout);
        }
    }
};

