func newRequestFromQuery(settings *backend.DataSourceInstanceSettings, customSettings dataSourceSettings, query dataSourceQuery) (*http.Request, error) {
	baseURL, err := url.Parse(settings.URL)
	if err != nil {
		return nil, err
	}

	// Parse the path separately to prevent path traversal
	pathURL, err := url.Parse(query.Path)
	if err != nil {
		return nil, fmt.Errorf("invalid path: %v", err)
	}

	// Resolve the path against the base URL
	finalURL := baseURL.ResolveReference(pathURL)

	// Validate that the final host matches the configured host
	if finalURL.Host != baseURL.Host {
		return nil, fmt.Errorf("invalid host: %s does not match configured host %s", finalURL.Host, baseURL.Host)
	}

	params := make(url.Values)
	for _, p := range query.Params {
		params.Set(p[0], p[1])
