func RequireSignedJWT(ctx context.Context, key []byte) error {
	rawjwt, ok := JWTFromGRPCRequest(ctx)
	if !ok {
		return status.Error(codes.Unauthenticated, "jwt token required")
	}

	tok, err := jwt.ParseSigned(rawjwt)
	if err != nil {
		return status.Errorf(codes.Unauthenticated, "invalid jwt: %v", err)
	}

	var claims struct {
		Expiry   *jwt.NumericDate `json:"exp,omitempty"`
		Type     string           `json:"typ,omitempty"`
		Audience string           `json:"aud,omitempty"`
	}
	err = tok.Claims(key, &claims)
	if err != nil {
		return status.Errorf(codes.Unauthenticated, "invalid jwt claims: %v", err)
	}

	if claims.Expiry == nil || time.Now().After(claims.Expiry.Time()) {
		return status.Error(codes.Unauthenticated, "jwt token expired")
	}

	// Reject service account tokens
	if claims.Type == "SA" || claims.Type == "serviceaccount" {
		return status.Error(codes.Unauthenticated, "service account tokens not allowed")
	}

	// Verify audience matches databroker service
	if claims.Audience != "databroker" {
		return status.Error(codes.Unauthenticated, "invalid jwt audience")
	}

	return nil
}

