func Init(ds model.DataStore) {
	once.Do(func() {
		log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)
		secret, err := ds.Property(context.TODO()).Get(consts.JWTSecretKey)
		if err != nil || secret == "" {
			// Generate secure random secret
			newSecret := make([]byte, 32)
			_, err := rand.Read(newSecret)
			if err != nil {
				log.Error("Failed to generate JWT secret", err)
				panic("Could not generate secure JWT secret")
			}
			hashedSecret := sha256.Sum256(newSecret)
			secret = hex.EncodeToString(hashedSecret[:])
			err = ds.Property(context.TODO()).Put(consts.JWTSecretKey, secret)
			if err != nil {
				log.Error("Failed to store JWT secret", err)
			}
			Secret = newSecret
		} else {
			// For backward compatibility with existing plaintext secrets
			// This ensures existing tokens continue to work
			if len(secret) != 64 { // Not a SHA256 hash
				Secret = []byte(secret)
			} else {
				// If stored value is already hashed, we need the original secret
				// This case shouldn't happen with the new implementation
				log.Warn("Found hashed JWT secret in DB but no original available")
				Secret = []byte(secret)
			}
		}
		TokenAuth = jwtauth.New("HS256", Secret, nil)
	})
}

