func (fs *Filesystem) Delete(p string) error {
	wg := sync.WaitGroup{}
	resolved := fs.unsafeFilePath(p)
	if !fs.unsafeIsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	// Block any whoopsies.
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	// Check if the path is a symbolic link before proceeding
	if isSymlink, err := isSymbolicLink(resolved); err != nil {
		return fmt.Errorf("failed to check if path is symlink: %v", err)
	} else if isSymlink {
		return errors.New("cannot delete symbolic links for security reasons")
	}

	if st, err := os.Lstat(resolved); err != nil {
		if !os.IsNotExist(err) {
			fs.error(err).Warn("error while attempting to stat file before deletion")
		}
	} else {
		if !st.IsDir() {
			fs.addDisk(-st.Size())
		} else {
			wg.Add(1)
			go func(wg *sync.WaitGroup, st os.FileInfo, resolved string) {
				defer wg.Done()
				if s, err := fs.DirectorySize(resolved); err == nil {
					fs.addDisk(-s)
				}
			}(&wg, st, resolved)
		}
	}

	wg.Wait()

	// Use Remove instead of RemoveAll to prevent recursive deletion through symlinks
	if err := os.Remove(resolved); err != nil {
		// If it's a directory and Remove failed, try removing contents first
		if st, err2 := os.Lstat(resolved); err2 == nil && st.IsDir() {
			// Remove directory contents securely
			if err := fs.secureRemoveDirectoryContents(resolved); err != nil {
				return err
			}
			// Then remove the directory itself
			return os.Remove(resolved)
		}
		return err
	}
	return nil
}

func isSymbolicLink(path string) (bool, error) {
	fi, err := os.Lstat(path)
	if err != nil {
		return false, err
	}
	return fi.Mode()&os.ModeSymlink != 0, nil
}

func (fs *Filesystem) secureRemoveDirectoryContents(dir string) error {
	files, err := os.ReadDir(dir)
	if err != nil {
		return err
	}

	for _, file := range files {
		filePath := filepath.Join(dir, file.Name())
		if isSymlink, err := isSymbolicLink(filePath); err != nil {
			return err
		} else if isSymlink {
			continue // Skip symbolic links
		}

		if err := fs.Delete(filePath); err != nil {
			return err
		}
	}
	return nil
}

