func (fs *Filesystem) Delete(p string) error {
	wg := sync.WaitGroup{}
	resolved := fs.unsafeFilePath(p)
	if !fs.unsafeIsInDataDirectory(resolved) {
		return NewBadPathResolution(p, resolved)
	}

	// Block any whoopsies.
	if resolved == fs.Path() {
		return errors.New("cannot delete root server directory")
	}

	// Check if the path is a symbolic link before proceeding
	if isSymlink, err := isSymbolicLink(resolved); err != nil {
		return fmt.Errorf("failed to check if path is symlink: %v", err)
	} else if isSymlink {
		return errors.New("cannot delete symbolic links for security reasons")
	}

	if st, err := os.Lstat(resolved); err != nil {
		if !os.IsNotExist(err) {
			fs.error(err).Warn("error while attempting to stat file before deletion")
		}
	} else {
		if !st.IsDir() {
			fs.addDisk(-st.Size())
		} else {
