function _typed(name, signatures) {
  var refs = new Refs();

  // Validate function name
  if (name && typeof name === 'string') {
    // Only allow alphanumeric characters, underscores and dollar signs
    if (!/^[a-zA-Z_$][0-9a-zA-Z_$]*$/.test(name)) {
      throw new Error('Invalid function name');
    }
  } else {
    name = '';
  }

  // parse signatures, expand them
  var _signatures = parseSignatures(signatures);
  if (_signatures.length == 0) {
    throw new Error('No signatures provided');
  }

  // filter all any type signatures
  var anys = filterAnyTypeSignatures(_signatures);

  // parse signatures into a node tree
  var node = parseTree(_signatures, [], anys);

  // generate code for the typed function
  var code = [];
  var _args = getArgs(maxParams(_signatures));
  code.push('function ' + name + '(' + _args.join(', ') + ') {');
  code.push('  "use strict";');
  code.push('  var name = \'' + name.replace(/\\/g, '\\\\').replace(/'/g, '\\\'') + '\';');
  code.push(node.toCode(refs, '  ', false));
  code.push('}');

  // generate body for the factory function
  var body = [
    refs.toCode(),
    'return ' + code.join('\n')
  ].join('\n');

  // evaluate the JavaScript code and attach function references
  var factory = (new Function(refs.name, 'createError', body));
  var fn = factory(refs, createError);

  // attach the signatures with sub-functions to the constructed function
  fn.signatures = mapSignatures(_signatures);

  return fn;
}

