function buildURL (source, reqBase) {
  const dest = new URL(source, reqBase)

  // if base is specified, verify the URL is properly contained
  if (reqBase) {
    const base = new URL(reqBase)

    // Verify protocol and host exactly match
    if (dest.protocol !== base.protocol || dest.host !== base.host) {
      throw new Error('source must be a relative path string')
    }

    // Verify path is properly contained within base path
    const basePath = base.pathname.endsWith('/') ? base.pathname : base.pathname + '/'
    if (!dest.pathname.startsWith(basePath)) {
      throw new Error('source path must be within base path')
    }

    // Prevent path traversal attempts
    if (dest.pathname.includes('/../') || dest.pathname.includes('/./') || 
        dest.pathname.endsWith('/..') || dest.pathname.endsWith('/.')) {
      throw new Error('invalid path traversal detected')
    }
  }

  return dest
}

