		return nil // Allow if both are missing (may be same-origin request)
	}

	// Parse host from request
	host := string(c.Host())
	if host == "" {
		return ErrInvalidHost
	}

	// Check Origin header if present
	if origin != "" {
		originURL, err := url.Parse(origin)
		if err != nil || originURL.Host != host {
			return ErrInvalidOrigin
		}
		return nil
	}

	// Check Referer header if present
	if referer != "" {
		refererURL, err := url.Parse(referer)
		if err != nil || refererURL.Host != host {
			return ErrInvalidReferer
		}
	}

	return nil
}

func generateSecureToken(length int) string {
	b := make([]byte, length)
	if _, err := rand.Read(b); err != nil {
		panic(err)
	}
	return base64.URLEncoding.EncodeToString(b)
}

