    return /token|password|credential|secret|private/i.test(envVar) && size(env[envVar].trim()) >= SECRET_MIN_SIZE;
  });

  const secretPatterns = toReplace.flatMap((envVar) => {
    const secret = env[envVar];
    const patterns = [escapeRegExp(secret)];

    // Add URL-encoded version if different from original
