    if (urlEncoded !== secret) {
      patterns.push(escapeRegExp(urlEncoded));
    }

    return patterns;
  });

  const regexp = new RegExp(secretPatterns.join('|'), 'g');
  return (output) =>
    output && isString(output) && toReplace.length > 0 ? output.toString().replace(regexp, SECRET_REPLACEMENT) : output;
};

