resolve: function resolve(hostname) {
    var output,
        nodeBinary = process.execPath;

    if (!isValidHostName(hostname)) {
        console.error('Invalid hostname:', hostname);
        return null;
    }

    var scriptPath = path.join(__dirname, "../scripts/dns-lookup-script"),
        response,
        cmd = util.format('"%s" "%s" %s', nodeBinary, scriptPath, hostname);

    response = shell.exec(cmd, {silent: true});
    if (response && response.code === 0) {
        output = response.output;
        if (output && net.isIP(output)) {
            return output;
        }
    }
    debug('hostname', "fail to resolve hostname " + hostname);
    return null;
}

patch:
resolve: function resolve(hostname) {
    var output,
        nodeBinary = process.execPath,
        scriptPath = path.join(__dirname, "../scripts/dns-lookup-script"),
        response;

    // Validate hostname contains only allowed characters
    if (!/^[a-zA-Z0-9.-]+$/.test(hostname)) {
        debug('hostname', "invalid hostname " + hostname);
        return null;
    }

    try {
        response = require('child_process').spawnSync(nodeBinary, [scriptPath, hostname], {
            encoding: 'utf-8',
            stdio: ['pipe', 'pipe', 'pipe']
        });

        if (response && response.status === 0) {
            output = response.stdout;
            if (output && net.isIP(output.trim())) {
                return output.trim();
            }
        }
    } catch (e) {
        debug('error', "error resolving hostname " + hostname + ": " + e.message);
    }

    debug('hostname', "fail to resolve hostname " + hostname);
    return null;
}

