def deny_uploads_containing_script_tag(uploaded_file):
    import re
    from django.core.exceptions import ValidationError
    from django.utils.translation import gettext_lazy as _

    # Validate file extension if name is available
    file_name = getattr(uploaded_file, 'name', '')
    if file_name:
        allowed_extensions = ['.txt', '.pdf', '.png', '.jpg', '.jpeg', '.gif', '.doc', '.docx', '.xls', '.xlsx']
        if file_name.lower().endswith('.svg'):
            raise ValidationError(_("SVG files are not allowed due to security concerns"))
        if not any(file_name.lower().endswith(ext) for ext in allowed_extensions):
            raise ValidationError(_("File type not allowed"))

    # Validate MIME type if available
    content_type = getattr(uploaded_file, 'content_type', '')
    if content_type:
        allowed_mime_types = [
            'text/plain', 'application/pdf', 'image/png', 'image/jpeg', 'image/gif',
            'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
        ]
        if content_type not in allowed_mime_types:
            raise ValidationError(_("File content type not allowed"))

    try:
        # Read file content safely in chunks
        content = b""
        for chunk in uploaded_file.chunks():
            content += chunk

            # Check for script tags and variations
            script_patterns = [
                rb"<\s*script",
                rb"<\s*svg\s*on",
                rb"<\s*img\s*[^>]*on",
                rb"<\s*a\s*[^>]*href\s*=\s*["']\s*javascript:"
            ]

            for pattern in script_patterns:
                if re.search(pattern, content, re.IGNORECASE):
                    raise ValidationError(_("File contains potentially dangerous content"))

            # Prevent memory exhaustion by limiting content size check
            if len(content) > 10 * 1024 * 1024:  # 10MB limit
                break

    except ValidationError:
        raise  # Re-raise validation errors
    except Exception as e:
        raise ValidationError(_("Error processing file"))
    finally:
        # Reset file pointer if possible
        if hasattr(uploaded_file, 'seek') and callable(uploaded_file.seek):
            uploaded_file.seek(0)

