    // Return escaped value or empty string if not found
    const value = data[key.trim()];
    return typeof value !== 'undefined' ? String(value).replace(/[&<>"']/g, escapeChar) : '';
  });

  // Helper function for escaping
  function escapeChar(c) {
    return {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;'
    }[c];
  }
}

