var path = require('path');
var cleanUrl = function(url) {
    // First check for null bytes or other dangerous characters
    if (url.indexOf('\0') !== -1 || /[<>:"|?*]/.test(url)) {
        return '';
    }

    // Remove all path traversal sequences
    while (url.includes('../') || url.includes('..\\')) {
        url = url.replace('../', '').replace('..\\', '');
    }

    // Remove remaining standalone '..' sequences
    url = url.replace(/\.\./g, '');

    // Now safely decode URI components
    url = decodeURIComponent(url);

    // Normalize the path and remove any remaining traversal attempts
    url = path.normalize(url).replace(/\.\./g, '');

    return url;
};

