        '-ss', start,
        '-i', sanitizedInput,
        '-t', duration,
        '-c', 'copy',
        '-y',
        `${output}.mp4`
      ];

      execFile('ffmpeg', args, (error, stdout, stderr) => {
        if (error) {
          reject(error);
          return;
        }
        resolve(`${output}.mp4`);
      });
    } else {
      reject(new Error("ffmpegdotjs could not find file"));
    }
  });
},

