trimvideo: (input, start, duration, output) => {
  return new Promise(function(resolve, reject) {
    // Validate input parameters
    if (typeof input !== 'string' || input.includes('..') || input.includes('|') || input.includes('&')) {
      reject(new Error("Invalid input file path"));
      return;
    }

    if (typeof start !== 'string' || !/^[0-9:.]+$/.test(start)) {
      reject(new Error("Invalid start time format. Expected format: HH:MM:SS or seconds"));
      return;
    }

    if (typeof duration !== 'string' || !/^[0-9:.]+$/.test(duration)) {
      reject(new Error("Invalid duration format. Expected format: HH:MM:SS or seconds"));
      return;
    }

    if (typeof output !== 'string' || /[\\/:*?"<>|&;$]/.test(output)) {
      reject(new Error("Invalid output filename. Cannot contain special characters"));
      return;
    }

    // Check if input file exists
    if (!fs.existsSync(input)) {
      reject(new Error("Input file does not exist"));
      return;
    }

    // Use execFile with array arguments
    const args = [
      '-hide_banner',
      '-loglevel', 'quiet',
      '-ss', start,
      '-i', input,
      '-t', duration,
      '-c', 'copy',
      '-y',
      `${output}.mp4`
    ];

    execFile('ffmpeg', args, (error, stdout, stderr) => {
      if (error) {
        reject(new Error(`FFmpeg processing failed: ${error.message}`));
        return;
      }
      resolve(`${output}.mp4`);
    });
  });
},

