const parseUrl = (url, normalize = false) => {
    // Constants
    const GIT_RE = /(^(git@|http(s)?:\/\/)([\w\.\-@]+)(\/|:))(([\~,\.\w,\-,\_,\/]+)(.git){0,1}((\/){0,1}))/

    // Blocklisted protocols
    const BLOCKED_PROTOCOLS = ['file:', 'ftp:', 'gopher:', 'ws:', 'wss:'];

    // Validate input
    if (typeof url !== "string" || !url.trim()) {
        const err = new Error("Invalid url.")
        err.subject_url = url
        throw err
    }

    // Check for blocked protocols
    const parsedUrl = new URL(url.startsWith('git@') ? `ssh://${url}` : url);
    if (BLOCKED_PROTOCOLS.includes(parsedUrl.protocol)) {
        const err = new Error(`Protocol ${parsedUrl.protocol} is not allowed.`);
        err.subject_url = url;
        throw err;
    }

    // Check for loopback/localhost
    if (['localhost', '127.0.0.1', '::1', '0.0.0.0'].includes(parsedUrl.hostname) || 
        parsedUrl.hostname.endsWith('.localhost') ||
        parsedUrl.hostname.startsWith('127.') ||
        parsedUrl.hostname === '[::1]') {
