function parseUrl(url, normalize = false) {
    if (typeof url !== "string" || !url.trim()) {
        throw new Error("Invalid url.")
    }

    // Handle protocol-less URLs
    let hasProtocol = url.includes('://');
    let isProtocolLess = url.startsWith('//');
    let isGitUrl = url.includes('git@') && url.includes(':');

    if (normalize) {
        if (typeof normalize !== "object") {
            normalize = {
                stripHash: false
            }
        }
        url = normalizeUrl(url, normalize)
    }

    // Handle Git URLs
    if (isGitUrl) {
        const [userHost, path] = url.split(':');
        const host = userHost.replace('git@', '');
        url = `ssh://git@${host}/${path}`;
    }

    // Validate URL format
    try {
        // Use URL constructor for basic validation
        new URL(isProtocolLess ? `https:${url}` : url);
    } catch (e) {
        throw new Error("Invalid url format.");
    }

    const parsed = parsePath(url);

    // Restore protocol-less URLs to their original form
    if (isProtocolLess && !hasProtocol) {
        parsed.protocol = '';
        parsed.protocols = [];
        parsed.href = parsed.href.replace(/^https?:/, '');
    }

    return parsed;
}

